@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private AppearanceModel? settings;
    private bool saving;
    private bool showSuccess;

    private static readonly string[] themes = ["Light", "Dark", "System"];
    private static readonly string[] fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var saved = await SettingsService.GetAppearanceAsync();
        settings = new AppearanceModel(saved);
    }

    private string GetPreviewClasses()
    {
        if (settings is null) return "";
        var classes = $"preview-theme-{settings.Theme.ToLowerInvariant()} preview-font-{settings.FontSize.ToLowerInvariant()}";
        if (settings.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        if (settings is null) return;
        saving = true;
        var updated = new AppearanceSettings(settings.Theme, settings.FontSize, settings.Language, settings.CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        saving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private class AppearanceModel
    {
        public string Theme { get; set; }
        public string FontSize { get; set; }
        public string Language { get; set; }
        public bool CompactMode { get; set; }

        public AppearanceModel(AppearanceSettings s)
        {
            Theme = s.Theme;
            FontSize = s.FontSize;
            Language = s.Language;
            CompactMode = s.CompactMode;
        }
    }
}

