        savedProfile = updated;
        saving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            profile = new ProfileModel(savedProfile);
        }
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private class ProfileModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileModel(UserProfile p)
        {
            DisplayName = p.DisplayName;
            Email = p.Email;
            AvatarUrl = p.AvatarUrl;
            Bio = p.Bio;
        }
    }
}
"}

{"path": "/tmp/sv-70821f979a864aebb3245cff5a7a7aae/Components/Pages/Settings/NotificationsSection.razor", "file_text": "@namespace sv_70821f979a864aebb3245cff5a7a7aae.Components.Pages.Settings
@using sv_70821f979a864aebb3245cff5a7a7aae.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (prefs is not null)
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="prefs.EmailNotifications" />
                <span>Email Notifications</span>
            </label>
            <label class="toggle-item">
                <input type="checkbox" @bind="prefs.PushNotifications" />
                <span>Push Notifications</span>
            </label>
            <label class="toggle-item">
                <input type="checkbox" @bind="prefs.WeeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                var isMuted = prefs.MutedChannels.Contains(channel);
                <label class="toggle-item">
                    <input type="checkbox" checked="@isMuted"
                           @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@saving">
                @(saving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast toast-success">Preferences saved!</div>
        }
    }
    else
    {
        <p>Loading notification preferences...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private PrefsModel? prefs;
    private bool saving;
    private bool showSuccess;

    private static readonly string[] allChannels = ["General", "Announcements", "Engineering", "Design", "Marketing", "Support"];

    protected override async Task OnInitializedAsync()
    {
        var saved = await SettingsService.GetNotificationPrefsAsync();
        prefs = new PrefsModel(saved);
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (prefs is null) return;
        if (muted && !prefs.MutedChannels.Contains(channel))
            prefs.MutedChannels.Add(channel);
        else if (!muted)
            prefs.MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        if (prefs is null) return;
        saving = true;
        var updated = new NotificationPrefs(prefs.EmailNotifications, prefs.PushNotifications, prefs.WeeklyDigest, new List<string>(prefs.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        saving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private class PrefsModel
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public PrefsModel(NotificationPrefs p)
        {
            EmailNotifications = p.EmailNotifications;
            PushNotifications = p.PushNotifications;
            WeeklyDigest = p.WeeklyDigest;
            MutedChannels = new List<string>(p.MutedChannels);
        }
    }
}
"}

{"path": "/tmp/sv-70821f979a864aebb3245cff5a7a7aae/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_70821f979a864aebb3245cff5a7a7aae.Components.Pages.Settings
@using sv_70821f979a864aebb3245cff5a7a7aae.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (security is not null)
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => showPasswordPanel = !showPasswordPanel">
                <span>Change Password</span>
                <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
            </button>

            @if (showPasswordPanel)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="toast toast-error">@passwordError</div>
                    }
                    @if (passwordSuccess)
                    {
                        <div class="toast toast-success">Password updated successfully!</div>
                    }

                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@changingPassword">
                        @(changingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(security.TwoFactorEnabled ? "status-enabled" : "status-disabled")"></span>
                <span>@(security.TwoFactorEnabled ? "Enabled" : "Disabled")</span>
            </div>
            @if (security.LastPasswordChange.HasValue)
            {
                <p class="last-change">Last password change: @security.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("MMM dd, yyyy HH:mm")</td>
                            <td>
                                @if (session != security.Sessions.First())
                                {
                                    <button class="btn-danger btn-small"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-session-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation>
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="button-group">
                        <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
    else
    {
        <p>Loading security settings...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? security;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;
    private bool changingPassword;
    private ActiveSession? sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
        finally
        {
            changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null || security is null) return;
        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        security = security with { Sessions = security.Sessions.Where(s => s.Id != sessionToRevoke.Id).ToList() };
        sessionToRevoke = null;
    }
}
"}

{"path": "/tmp/sv-70821f979a864aebb3245cff5a7a7aae/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_70821f979a864aebb3245cff5a7a7aae.Components.Pages.Settings
@using sv_70821f979a864aebb3245cff5a7a7aae.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (settings is not null)
    {
        <!-- Theme -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in themes)
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(settings.Theme == theme)"
                               @onchange="() => settings.Theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in fontSizes)
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(settings.FontSize == size)"
                               @onchange="() => settings.FontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="settings.Language">
                @foreach (var lang in languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="form-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="settings.CompactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <p class="preview-text">This is how your content will look with the selected settings.</p>
            <div class="preview-card">
                <strong>Sample Card</strong>
                <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@saving">
                @(saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast toast-success">Appearance settings saved!</div>
        }
    }
    else
    {
        <p>Loading appearance settings...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private AppearanceModel? settings;
    private bool saving;
    private bool showSuccess;

    private static readonly string[] themes = ["Light", "Dark", "System"];
    private static readonly string[] fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var saved = await SettingsService.GetAppearanceAsync();
        settings = new AppearanceModel(saved);
    }

    private string GetPreviewClasses()
    {
        if (settings is null) return "";
        var classes = $"preview-theme-{settings.Theme.ToLowerInvariant()} preview-font-{settings.FontSize.ToLowerInvariant()}";
        if (settings.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        if (settings is null) return;
        saving = true;
        var updated = new AppearanceSettings(settings.Theme, settings.FontSize, settings.Language, settings.CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        saving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private class AppearanceModel
    {
        public string Theme { get; set; }
        public string FontSize { get; set; }
        public string Language { get; set; }
        public bool CompactMode { get; set; }

        public AppearanceModel(AppearanceSettings s)
        {
            Theme = s.Theme;
            FontSize = s.FontSize;
            Language = s.Language;
            CompactMode = s.CompactMode;
        }
    }
}
"}

