namespace sv_70821f979a864aebb3245cff5a7a7aae.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_70821f979a864aebb3245cff5a7a7aae.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_70821f979a864aebb3245cff5a7a7aae.Components.Pages.Settings
@using sv_70821f979a864aebb3245cff5a7a7aae.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (profile is not null)
    {
        <div class="avatar-preview">
            <img src="@profile.AvatarUrl" alt="Avatar" class="avatar-image" />
            <p class="avatar-url">@profile.AvatarUrl</p>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="profile.DisplayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="profile.Email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" rows="4" @bind="profile.Bio"></textarea>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@saving">
                @(saving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn-secondary" @onclick="DiscardChanges" disabled="@saving">
                Discard Changes
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast toast-success">Profile saved successfully!</div>
        }
    }
    else
    {
        <p>Loading profile...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private ProfileModel? profile;
    private UserProfile? savedProfile;
    private bool saving;
    private bool showSuccess;

    protected override async Task OnInitializedAsync()
    {
        savedProfile = await SettingsService.GetProfileAsync();
        profile = new ProfileModel(savedProfile);
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;
        saving = true;
        var updated = new UserProfile(profile.DisplayName, profile.Email, profile.AvatarUrl, profile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        saving = false;
        showSuccess = true;
        _ = HideToastAsync();
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            profile = new ProfileModel(savedProfile);
        }
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private class ProfileModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileModel(UserProfile p)
        {
            DisplayName = p.DisplayName;
            Email = p.Email;
            AvatarUrl = p.AvatarUrl;
            Bio = p.Bio;
        }
    }
}

