toolArgs.file_text:
@page "/settings"
@namespace sv_70821f979a864aebb3245cff5a7a7aae.Components.Pages.Settings
@using sv_70821f979a864aebb3245cff5a7a7aae.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "Notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "Security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "Appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

/* Sidebar */
::deep .settings-sidebar {
    width: 240px;
    background: var(--bs-body-bg, #f8f9fa);
    border-right: 1px solid var(--bs-border-color, #dee2e6);
    padding: 1rem 0;
}

::deep .settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    font-size: 0.95rem;
}

::deep .settings-sidebar li:hover {
    background: rgba(0, 0, 0, 0.04);
}

::deep .settings-sidebar li.active {
    background: rgba(13, 110, 253, 0.08);
    border-left-color: #0d6efd;
    font-weight: 600;
    color: #0d6efd;
}

/* Section common styles */
::deep .settings-section {
    max-width: 720px;
}

::deep .settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

::deep .settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    font-weight: 600;
}

/* Form elements */
::deep .form-group {
    margin-bottom: 1.25rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    font-size: 0.9rem;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.2s;
}

::deep .form-group input:focus,
::deep .form-group textarea:focus,
::deep .form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

/* Buttons */
::deep .button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn-primary {
    padding: 0.5rem 1.25rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.2s;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-secondary {
    padding: 0.5rem 1.25rem;
    background: white;
    color: #333;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.2s;
}

::deep .btn-secondary:hover:not(:disabled) {
    background: #f8f9fa;
}

::deep .btn-danger {
    padding: 0.5rem 1.25rem;
    background: #dc3545;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
}

::deep .btn-danger:hover {
    background: #bb2d3b;
}

::deep .btn-small {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast messages */
::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

::deep .toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

::deep .toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Toggle items */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

::deep .toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    cursor: pointer;
}

/* Channel list */
::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 6px;
}

/* Avatar */
::deep .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

::deep .avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

::deep .avatar-url {
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Expandable panel */
::deep .expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

::deep .panel-header:hover {
    background: #e9ecef;
}

::deep .panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* TFA */
::deep .tfa-section {
    margin-bottom: 1.5rem;
}

::deep .tfa-status {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.9rem;
}

::deep .status-indicator {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

::deep .status-enabled {
    background: #198754;
}

::deep .status-disabled {
    background: #dc3545;
}

::deep .last-change {
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Sessions table */
::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.625rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

::deep .sessions-table th {
    font-weight: 600;
    background: #f8f9fa;
}

::deep .current-session-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    background: #e2e3e5;
    border-radius: 4px;
    color: #41464b;
}

/* Radio group */
::deep .radio-group {
    display: flex;
    gap: 1.25rem;
}

::deep .radio-item {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Preview area */
::deep .preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    transition: all 0.3s ease;
}

::deep .preview-area h4 {
    margin: 0 0 0.75rem;
}

::deep .preview-card {
    padding: 1rem;
    background: rgba(0, 0, 0, 0.03);
    border-radius: 6px;
    margin-top: 0.75rem;
}

::deep .preview-theme-dark {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #333;
}

::deep .preview-theme-dark .preview-card {
    background: rgba(255, 255, 255, 0.08);
}

::deep .preview-theme-light {
    background: #ffffff;
    color: #333;
}

::deep .preview-font-small {
    font-size: 0.8rem;
}

::deep .preview-font-medium {
    font-size: 0.95rem;
}

::deep .preview-font-large {
    font-size: 1.1rem;
}

::deep .preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

::deep .preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

/* Modal */
::deep .modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .modal-dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
}

::deep .modal-dialog h4 {
    margin: 0 0 0.75rem;
}

::deep .modal-dialog p {
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

